def M(q, correct, wrong, exp, type="اختيار من متعدد"):
    QRAW.append({"type": type, "q": q, "correct": correct, "wrong": wrong, "exp": exp})
def TF(q, ok, exp):
    QRAW.append({"type": "صح أو خطأ", "q": q, "tf": ok, "exp": exp})
def A(q, correct, wrong, exp):
    M(q, correct, wrong, exp, type="الأعلام والآراء")

